import os
import re
from collections import defaultdict

# Find all functions/methods declared in internal/ (non-test files)
declarations = defaultdict(lambda: {'file': '', 'type': ''})

for root, dirs, files in os.walk('internal'):
    for file in files:
        if file.endswith('.go') and not file.endswith('_test.go'):
            filepath = os.path.join(root, file)
            try:
                with open(filepath, 'r') as f:
                    content = f.read()

                    # Find package-level functions: func FunctionName(
                    for match in re.finditer(r'^func ([A-Z][A-Za-z0-9_]*)\s*\(', content, re.MULTILINE):
                        func_name = match.group(1)
                        declarations[func_name]['file'] = filepath
                        declarations[func_name]['type'] = 'func'

                    # Find methods: func (receiver) MethodName(
                    for match in re.finditer(r'^func\s*\([^)]*\)\s*([A-Z][A-Za-z0-9_]*)\s*\(', content, re.MULTILINE):
                        method_name = match.group(1)
                        declarations[method_name]['file'] = filepath
                        declarations[method_name]['type'] = 'method'
            except:
                pass

# Now count references for each declared symbol
call_counts = {}

for root, dirs, files in os.walk('.'):
    for file in files:
        if file.endswith('.go') and not file.endswith('_test.go'):
            filepath = os.path.join(root, file)
            try:
                with open(filepath, 'r') as f:
                    content = f.read()

                    for symbol, info in declarations.items():
                        # Skip if this is the declaration file
                        if filepath != info['file']:
                            # Count occurrences of the symbol followed by '(' or '.'
                            pattern = rf'\b{re.escape(symbol)}\s*\('
                            matches = len(re.findall(pattern, content))
                            if matches > 0:
                                if symbol not in call_counts:
                                    call_counts[symbol] = {'count': 0, 'file': info['file'], 'type': info['type']}
                                call_counts[symbol]['count'] += matches
            except:
                pass

# Sort by call count
sorted_symbols = sorted(call_counts.items(), key=lambda x: x[1]['count'], reverse=True)

print("Top 30 symbols by call count:")
for i, (symbol, info) in enumerate(sorted_symbols[:30], 1):
    print(f"{i}. {symbol}: {info['count']} calls ({info['type']}) - {info['file']}")
EOF

